// Simplified from flow/include/flow/Buggify.h in FoundationDB
const double P_ACTIVATED = 0.25;  // per site, decided once per run
const double P_FIRES     = 0.25;  // per evaluation, if active
std::unordered_map<Site, bool> active;

bool buggify(Site site) {
  if (!simulationEnabled) return false;      // always off in production
  if (!active.count(site))
    active[site] = rng.random01() < P_ACTIVATED;
  return active[site] && rng.random01() < P_FIRES;
}

// At a call site in server code:
if (buggify(HERE)) {
  co_await delay(rng.random01() * 5.0);      // unusual but legal: a slow reply
}
